WITH base AS (SELECT * FROM web_events WHERE page NOT IN ('/checkout', '/home', '/product') AND (event_type = 'click' OR page = '/search')), summary AS (SELECT DATE_TRUNC('MONTH', event_time) AS event_month, ROUND((100 * SUM(CASE WHEN page = '/cart' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cart, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM base GROUP BY DATE_TRUNC('MONTH', event_time)) SELECT event_month, pct_cart FROM summary ORDER BY pct_cart
